class Decimal
{
    private const SCALE = 16;

    public static function add($a, $b): string
    {
        return bcadd(self::normalize($a), self::normalize($b), self::SCALE);
    }

    public static function sub($a, $b): string
    {
        return bcsub(self::normalize($a), self::normalize($b), self::SCALE);
    }

    public static function mul($a, $b): string
    {
        return bcmul(self::normalize($a), self::normalize($b), self::SCALE);
    }

    public static function div($a, $b): string
    {
        $bNormalized = self::normalize($b);
        if (bccomp($bNormalized, '0', self::SCALE) === 0) {
            return '0'; // Handle division by zero gracefully or throw error
        }
        return bcdiv(self::normalize($a), $bNormalized, self::SCALE);
    }

    public static function comp($a, $b): int
    {
        return bccomp(self::normalize($a), self::normalize($b), self::SCALE);
    }

    public static function min($a, $b): string
    {
        $normA = self::normalize($a);
        $normB = self::normalize($b);
        return bccomp($normA, $normB, self::SCALE) <= 0 ? $normA : $normB;
    }

    public static function max($a, $b): string
    {
        $normA = self::normalize($a);
        $normB = self::normalize($b);
        return bccomp($normA, $normB, self::SCALE) >= 0 ? $normA : $normB;
    }

    public static function truncate($value, int $decimals): string
    {
        $val = self::normalize($value);
        if (strpos($val, '.') === false) {
            return $decimals > 0 ? $val . '.' . str_repeat('0', $decimals) : $val;
        }

        [$integral, $fraction] = explode('.', $val);
        $truncatedFraction = substr($fraction, 0, $decimals);
