    public static function format($value, int $decimals = 2): string
    {
        $truncated = self::truncate($value, $decimals);
        if (strpos($truncated, '.') === false) {
            $integral = $truncated;
            $fraction = '';
        } else {
            [$integral, $fraction] = explode('.', $truncated);
        }

        $isNegative = str_starts_with($integral, '-');
        $cleanIntegral = ltrim($integral, '-');
        $formattedIntegral = preg_replace('/\B(?=(\d{3})+(?!\d))/', ',', $cleanIntegral);
        if ($isNegative) {
            $formattedIntegral = '-' . $formattedIntegral;
        }

        return $decimals > 0 ? $formattedIntegral . '.' . $fraction : $formattedIntegral;
    }

    private static function normalize($value): string
    {
        if ($value === null || $value === '') {
            return '0';
        }

        $value = (string) $value;

        // Handle scientific notation (e.g., 2.5E-8)
        if (strpos(strtolower($value), 'e') !== false) {
            // Use number_format to convert to full decimal string without locale formatting
            // 16 decimals is our scale
            return number_format((float) $value, self::SCALE, '.', '');
        }

        return $value;
    }

    public static function trimZeros($value): string
    {
        $val = self::normalize($value);
        if (strpos($val, '.') === false) {
            return $val;
        }
        $trimmed = rtrim(rtrim($val, '0'), '.');
        return $trimmed === '' ? '0' : $trimmed;
    }

    public static function trimZero($value): string
    {
        return self::trimZeros($value);
